INSERT INTO rol_permiso (id_rol, id_permiso)
SELECT r.id_rol, p.id_permiso
FROM v
JOIN rol r ON r.nombre = v.rol
JOIN permiso p ON p.nombre = v.permiso
WHERE NOT EXISTS (SELECT 1 FROM rol_permiso x WHERE x.id_rol = r.id_rol AND x.id_permiso = p.id_permiso)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM rol_permiso) < 100 THEN 100 - (SELECT COUNT(*) FROM rol_permiso) ELSE 0 END;

