INSERT INTO usuario (nombre, apellido, email, password, id_rol, estado, fecha_registro)
SELECT CAST(v.nombre AS VARCHAR(80)), CAST(v.apellido AS VARCHAR(80)), CAST(v.email AS VARCHAR(120)), CAST(v.password AS VARCHAR(200)), r.id_rol, CAST(v.estado AS VARCHAR(20)), CAST(v.fecha AS TIMESTAMP)
FROM v
JOIN rol r ON r.nombre = v.rol
WHERE NOT EXISTS (SELECT 1 FROM usuario x WHERE x.email = v.email)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM usuario) < 100 THEN 100 - (SELECT COUNT(*) FROM usuario) ELSE 0 END;

