INSERT INTO servicio_financiero (nombre, tipo_servicio, descripcion, estado)
SELECT CAST(v.nombre AS VARCHAR(120)), CAST(v.tipo AS VARCHAR(60)), CAST(v.descripcion AS TEXT), CAST(v.estado AS VARCHAR(20))
FROM v
WHERE NOT EXISTS (SELECT 1 FROM servicio_financiero x WHERE x.nombre = v.nombre)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM servicio_financiero) < 100 THEN 100 - (SELECT COUNT(*) FROM servicio_financiero) ELSE 0 END;

