INSERT INTO cliente (tipo_documento, documento, nombres, apellidos, fecha_nacimiento, telefono, correo, direccion, estado, fecha_registro)
SELECT CAST(v.tipo AS VARCHAR(20)), CAST(v.documento AS VARCHAR(20)), CAST(v.nombres AS VARCHAR(120)), CAST(v.apellidos AS VARCHAR(120)), CAST(v.nacimiento AS DATE), CAST(v.telefono AS VARCHAR(30)), CAST(v.correo AS VARCHAR(120)), CAST(v.direccion AS VARCHAR(200)), CAST(v.estado AS VARCHAR(20)), CAST(v.fecha AS TIMESTAMP)
FROM v
WHERE NOT EXISTS (SELECT 1 FROM cliente x WHERE x.documento = v.documento)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM cliente) < 100 THEN 100 - (SELECT COUNT(*) FROM cliente) ELSE 0 END;

