INSERT INTO cliente_acceso (id_cliente, password)
SELECT c.id_cliente, CAST(v.clave AS VARCHAR(200))
FROM v
JOIN cliente c ON c.documento = v.documento
WHERE NOT EXISTS (SELECT 1 FROM cliente_acceso a WHERE a.id_cliente = c.id_cliente);

