INSERT INTO cliente_servicio (id_cliente, id_servicio, fecha_inicio, fecha_fin, estado)
SELECT c.id_cliente, s.id_servicio, CAST(v.inicio AS DATE), CAST(v.fin AS DATE), CAST(v.estado AS VARCHAR(20))
FROM v
JOIN cliente c ON c.documento = v.documento
JOIN servicio_financiero s ON s.nombre = v.servicio
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM cliente_servicio) < 100 THEN 100 - (SELECT COUNT(*) FROM cliente_servicio) ELSE 0 END;

