INSERT INTO tipo_cambio (moneda_origen, moneda_destino, compra, venta, fecha_inicio, estado)
SELECT CAST(v.origen AS VARCHAR(10)), CAST(v.destino AS VARCHAR(10)), CAST(v.compra AS NUMERIC(12,4)), CAST(v.venta AS NUMERIC(12,4)), CAST(v.inicio AS DATE), CAST(v.estado AS VARCHAR(20))
FROM v
WHERE NOT EXISTS (SELECT 1 FROM tipo_cambio x WHERE x.moneda_origen = v.origen AND x.moneda_destino = v.destino AND x.fecha_inicio = CAST(v.inicio AS DATE))
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM tipo_cambio) < 100 THEN 100 - (SELECT COUNT(*) FROM tipo_cambio) ELSE 0 END;

