INSERT INTO operacion (id_cliente, id_tipo_cambio, tipo_operacion, moneda_origen, moneda_destino, monto, tipo_cambio, total_entregar, total_recibir, estado, fecha_operacion)
SELECT c.id_cliente, (SELECT t.id_tipo_cambio FROM tipo_cambio t WHERE t.moneda_origen = v.origen AND t.moneda_destino = v.destino AND t.estado = 'ACTIVO' ORDER BY t.fecha_inicio DESC, t.id_tipo_cambio DESC LIMIT 1), CAST(v.tipo AS VARCHAR(30)), CAST(v.origen AS VARCHAR(10)), CAST(v.destino AS VARCHAR(10)), CAST(v.monto AS NUMERIC(14,2)), CAST(v.tc AS NUMERIC(12,4)), CAST(v.entregar AS NUMERIC(14,2)), CAST(v.recibir AS NUMERIC(14,2)), CAST(v.estado AS VARCHAR(20)), CAST(v.fecha AS TIMESTAMP)
FROM v
JOIN cliente c ON c.documento = v.documento
WHERE NOT EXISTS (SELECT 1 FROM operacion x WHERE x.tipo_operacion = v.tipo AND x.monto = CAST(v.monto AS NUMERIC(14,2)))
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM operacion WHERE tipo_operacion = 'CAMBIO') < 100 THEN 100 - (SELECT COUNT(*) FROM operacion WHERE tipo_operacion = 'CAMBIO') ELSE 0 END;

