INSERT INTO operacion (id_cliente, id_tipo_cambio, tipo_operacion, moneda_origen, moneda_destino, monto, tipo_cambio, total_entregar, total_recibir, estado, fecha_operacion)
SELECT c.id_cliente, CAST(NULL AS INTEGER), CAST(v.tipo AS VARCHAR(30)), CAST(v.origen AS VARCHAR(10)), CAST(v.destino AS VARCHAR(10)), CAST(v.monto AS NUMERIC(14,2)), CAST(v.tc AS NUMERIC(12,4)), CAST(v.entregar AS NUMERIC(14,2)), CAST(v.recibir AS NUMERIC(14,2)), CAST(v.estado AS VARCHAR(20)), CAST(v.fecha AS TIMESTAMP)
FROM v
JOIN cliente c ON c.documento = v.documento
WHERE NOT EXISTS (SELECT 1 FROM operacion x WHERE x.tipo_operacion = v.tipo AND x.monto = CAST(v.monto AS NUMERIC(14,2)))
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM operacion WHERE tipo_operacion = 'EMPENO') < 100 THEN 100 - (SELECT COUNT(*) FROM operacion WHERE tipo_operacion = 'EMPENO') ELSE 0 END;

