INSERT INTO prestamo (id_operacion, monto_prestamo, tasa_interes, plazo_meses, cuota_mensual, fecha_inicio, fecha_vencimiento, saldo_pendiente, estado)
SELECT o.id_operacion, CAST(v.monto AS NUMERIC(14,2)), CAST(v.tasa AS NUMERIC(6,3)), CAST(v.plazo AS INTEGER), CAST(v.cuota AS NUMERIC(14,2)), CAST(v.inicio AS DATE), CAST(v.vence AS DATE), CAST(v.saldo AS NUMERIC(14,2)), CAST(v.estado AS VARCHAR(20))
FROM v
JOIN operacion o ON o.tipo_operacion = 'PRESTAMO' AND o.monto = CAST(v.monto AS NUMERIC(14,2))
WHERE NOT EXISTS (SELECT 1 FROM prestamo x WHERE x.id_operacion = o.id_operacion)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM prestamo) < 100 THEN 100 - (SELECT COUNT(*) FROM prestamo) ELSE 0 END;

