INSERT INTO articulo (id_cliente, descripcion, categoria, marca, modelo, numero_serie, estado_fisico, valor_estimado, fecha_registro, estado)
SELECT c.id_cliente, CAST(v.descripcion AS VARCHAR(200)), CAST(v.categoria AS VARCHAR(60)), CAST(v.marca AS VARCHAR(60)), CAST(v.modelo AS VARCHAR(60)), CAST(v.serie AS VARCHAR(80)), CAST(v.fisico AS VARCHAR(60)), CAST(v.valor AS NUMERIC(14,2)), CAST(v.fecha AS DATE), CAST(v.estado AS VARCHAR(20))
FROM v
JOIN cliente c ON c.documento = v.documento
WHERE NOT EXISTS (SELECT 1 FROM articulo x WHERE x.numero_serie = v.serie)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM articulo) < 100 THEN 100 - (SELECT COUNT(*) FROM articulo) ELSE 0 END;

