INSERT INTO empeno (id_operacion, id_articulo, monto_prestamo, tasa_interes, plazo_dias, fecha_empeno, fecha_vencimiento, saldo_pendiente, estado)
SELECT o.id_operacion, a.id_articulo, CAST(v.monto AS NUMERIC(14,2)), CAST(v.tasa AS NUMERIC(6,3)), CAST(v.plazo AS INTEGER), CAST(v.inicio AS DATE), CAST(v.vence AS DATE), CAST(v.saldo AS NUMERIC(14,2)), CAST(v.estado AS VARCHAR(20))
FROM v
JOIN operacion o ON o.tipo_operacion = 'EMPENO' AND o.monto = CAST(v.monto AS NUMERIC(14,2))
JOIN articulo a ON a.numero_serie = v.serie
WHERE NOT EXISTS (SELECT 1 FROM empeno x WHERE x.id_operacion = o.id_operacion)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM empeno) < 100 THEN 100 - (SELECT COUNT(*) FROM empeno) ELSE 0 END;

