INSERT INTO comprobante (id_operacion, numero_comprobante, tipo_comprobante, fecha_emision, monto_total, estado)
SELECT o.id_operacion, CAST(v.numero AS VARCHAR(40)), CAST(v.tipo_comp AS VARCHAR(30)), CAST(v.fecha AS TIMESTAMP), CAST(v.total AS NUMERIC(14,2)), CAST(v.estado AS VARCHAR(20))
FROM v
JOIN operacion o ON o.tipo_operacion = v.tipo AND o.monto = CAST(v.monto AS NUMERIC(14,2))
WHERE NOT EXISTS (SELECT 1 FROM comprobante x WHERE x.numero_comprobante = v.numero)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM comprobante) < 100 THEN 100 - (SELECT COUNT(*) FROM comprobante) ELSE 0 END;

