INSERT INTO venta (id_cliente, id_servicio, fecha_venta, monto, importe, estado)
SELECT c.id_cliente, s.id_servicio, CAST(v.fecha AS TIMESTAMP), CAST(v.monto AS NUMERIC(14,2)), CAST(v.importe AS NUMERIC(14,2)), CAST(v.estado AS VARCHAR(20))
FROM v
JOIN cliente c ON c.documento = v.documento
JOIN servicio_financiero s ON s.nombre = v.servicio
WHERE NOT EXISTS (SELECT 1 FROM venta x WHERE x.importe = CAST(v.importe AS NUMERIC(14,2)) AND x.id_cliente = c.id_cliente)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM venta) < 100 THEN 100 - (SELECT COUNT(*) FROM venta) ELSE 0 END;

