INSERT INTO detalle_venta (id_venta, descripcion, cantidad, precio_unitario, subtotal)
SELECT ve.id_venta, CAST(v.descripcion AS VARCHAR(200)), CAST(v.cantidad AS INTEGER), CAST(v.precio AS NUMERIC(14,2)), CAST(v.subtotal AS NUMERIC(14,2))
FROM v
JOIN venta ve ON ve.importe = CAST(v.importe AS NUMERIC(14,2))
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM detalle_venta) < 100 THEN 100 - (SELECT COUNT(*) FROM detalle_venta) ELSE 0 END;

