INSERT INTO producto (codigo, nombre, descripcion, categoria, unidad_medida, stock_actual, stock_minimo, estado)
SELECT CAST(v.codigo AS VARCHAR(40)), CAST(v.nombre AS VARCHAR(120)), CAST(v.descripcion AS TEXT), CAST(v.categoria AS VARCHAR(60)), CAST(v.unidad AS VARCHAR(30)), CAST(v.stock AS INTEGER), CAST(v.minimo AS INTEGER), CAST(v.estado AS VARCHAR(20))
FROM v
WHERE NOT EXISTS (SELECT 1 FROM producto x WHERE x.codigo = v.codigo)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM producto) < 100 THEN 100 - (SELECT COUNT(*) FROM producto) ELSE 0 END;

