SELECT p.id_producto, CAST(v.ubicacion AS VARCHAR(80)), CAST(v.cantidad AS INTEGER), CAST(v.fecha AS TIMESTAMP)
FROM v
JOIN producto p ON p.codigo = v.codigo
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM inventario) < 100 THEN 100 - (SELECT COUNT(*) FROM inventario) ELSE 0 END;

