INSERT INTO movimiento_inventario (id_producto, tipo_movimiento, cantidad, motivo, fecha_movimiento)
SELECT p.id_producto, CAST(v.tipo AS VARCHAR(20)), CAST(v.cantidad AS INTEGER), CAST(v.motivo AS VARCHAR(200)), CAST(v.fecha AS TIMESTAMP)
FROM v
JOIN producto p ON p.codigo = v.codigo
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM movimiento_inventario) < 100 THEN 100 - (SELECT COUNT(*) FROM movimiento_inventario) ELSE 0 END;

