INSERT INTO proveedor (razon_social, ruc, contacto, telefono, correo, direccion, estado)
SELECT CAST(v.razon AS VARCHAR(150)), CAST(v.ruc AS VARCHAR(20)), CAST(v.contacto AS VARCHAR(120)), CAST(v.telefono AS VARCHAR(30)), CAST(v.correo AS VARCHAR(120)), CAST(v.direccion AS VARCHAR(200)), CAST(v.estado AS VARCHAR(20))
FROM v
WHERE NOT EXISTS (SELECT 1 FROM proveedor x WHERE x.ruc = v.ruc)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM proveedor) < 100 THEN 100 - (SELECT COUNT(*) FROM proveedor) ELSE 0 END;

