INSERT INTO movimiento_logistica (id_proveedor, tipo_movimiento, descripcion, cantidad, fecha_movimiento, estado)
SELECT p.id_proveedor, CAST(v.tipo AS VARCHAR(30)), CAST(v.descripcion AS TEXT), CAST(v.cantidad AS INTEGER), CAST(v.fecha AS TIMESTAMP), CAST(v.estado AS VARCHAR(20))
FROM v
JOIN proveedor p ON p.ruc = v.ruc
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM movimiento_logistica) < 100 THEN 100 - (SELECT COUNT(*) FROM movimiento_logistica) ELSE 0 END;

