INSERT INTO prospecto (nombres, apellidos, documento, telefono, correo, origen, estado, fecha_registro)
SELECT CAST(v.nombres AS VARCHAR(120)), CAST(v.apellidos AS VARCHAR(120)), CAST(v.documento AS VARCHAR(20)), CAST(v.telefono AS VARCHAR(30)), CAST(v.correo AS VARCHAR(120)), CAST(v.origen AS VARCHAR(60)), CAST(v.estado AS VARCHAR(20)), CAST(v.fecha AS TIMESTAMP)
FROM v
WHERE NOT EXISTS (SELECT 1 FROM prospecto x WHERE x.documento = v.documento)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM prospecto) < 100 THEN 100 - (SELECT COUNT(*) FROM prospecto) ELSE 0 END;

