INSERT INTO campania (nombre, descripcion, fecha_inicio, fecha_fin, presupuesto, canal, estado)
SELECT CAST(v.nombre AS VARCHAR(120)), CAST(v.descripcion AS TEXT), CAST(v.inicio AS DATE), CAST(v.fin AS DATE), CAST(v.presupuesto AS NUMERIC(14,2)), CAST(v.canal AS VARCHAR(60)), CAST(v.estado AS VARCHAR(20))
FROM v
WHERE NOT EXISTS (SELECT 1 FROM campania x WHERE x.nombre = v.nombre)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM campania) < 100 THEN 100 - (SELECT COUNT(*) FROM campania) ELSE 0 END;

