INSERT INTO campania_prospecto (id_campania, id_prospecto, fecha_contacto, resultado, estado)
SELECT c.id_campania, p.id_prospecto, CAST(v.fecha AS DATE), CAST(v.resultado AS VARCHAR(120)), CAST(v.estado AS VARCHAR(20))
FROM v
JOIN campania c ON c.nombre = v.campania
JOIN prospecto p ON p.documento = v.documento
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM campania_prospecto) < 100 THEN 100 - (SELECT COUNT(*) FROM campania_prospecto) ELSE 0 END;

