INSERT INTO actividad_marketing (id_prospecto, id_campania, tipo_actividad, descripcion, fecha_actividad)
SELECT p.id_prospecto, c.id_campania, CAST(v.tipo AS VARCHAR(60)), CAST(v.descripcion AS TEXT), CAST(v.fecha AS TIMESTAMP)
FROM v
JOIN prospecto p ON p.documento = v.documento
JOIN campania c ON c.nombre = v.campania
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM actividad_marketing) < 100 THEN 100 - (SELECT COUNT(*) FROM actividad_marketing) ELSE 0 END;

