INSERT INTO linea_produccion (codigo, nombre, descripcion, estado)
SELECT CAST(v.codigo AS VARCHAR(40)), CAST(v.nombre AS VARCHAR(120)), CAST(v.descripcion AS TEXT), CAST(v.estado AS VARCHAR(20))
FROM v
WHERE NOT EXISTS (SELECT 1 FROM linea_produccion x WHERE x.codigo = v.codigo)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM linea_produccion) < 100 THEN 100 - (SELECT COUNT(*) FROM linea_produccion) ELSE 0 END;

