INSERT INTO orden_produccion (id_producto, id_linea, cantidad, fecha_inicio, fecha_fin_estimada, fecha_fin_real, avance, estado, observaciones)
SELECT p.id_producto, l.id_linea, CAST(v.cantidad AS INTEGER), CAST(v.inicio AS DATE), CAST(v.fin_est AS DATE), CAST(v.fin_real AS DATE), CAST(v.avance AS NUMERIC(5,2)), CAST(v.estado AS VARCHAR(20)), CAST(v.obs AS TEXT)
FROM v
JOIN producto p ON p.codigo = v.producto
JOIN linea_produccion l ON l.codigo = v.linea
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM orden_produccion) < 100 THEN 100 - (SELECT COUNT(*) FROM orden_produccion) ELSE 0 END;

