INSERT INTO expediente_aprobacion (codigo, area, solicitante, monto, impacto, descripcion, estado, fecha_solicitud, fecha_resolucion)
SELECT CAST(v.codigo AS VARCHAR(40)), CAST(v.area AS VARCHAR(80)), CAST(v.solicitante AS VARCHAR(120)), CAST(v.monto AS NUMERIC(14,2)), CAST(v.impacto AS VARCHAR(60)), CAST(v.descripcion AS TEXT), CAST(v.estado AS VARCHAR(20)), CAST(v.solicitud AS TIMESTAMP), CAST(v.resolucion AS TIMESTAMP)
FROM v
WHERE NOT EXISTS (SELECT 1 FROM expediente_aprobacion x WHERE x.codigo = v.codigo)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM expediente_aprobacion) < 100 THEN 100 - (SELECT COUNT(*) FROM expediente_aprobacion) ELSE 0 END;

-- ---- Direccion: decisiones (100) ----
WITH v (n, codigo, tipo, descripcion, fecha, estado) AS (VALUES
  (1, 'EXP-004', 'APROBAR', 'DD-0001: decision de direccion sobre EXP-004', CURRENT_TIMESTAMP - INTERVAL '94 days 3 hours 33 minutes', 'VIGENTE'),
