INSERT INTO decision_direccion (id_expediente, tipo_decision, descripcion, fecha_decision, estado)
SELECT e.id_expediente, CAST(v.tipo AS VARCHAR(40)), CAST(v.descripcion AS TEXT), CAST(v.fecha AS TIMESTAMP), CAST(v.estado AS VARCHAR(20))
FROM v
JOIN expediente_aprobacion e ON e.codigo = v.codigo
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM decision_direccion) < 100 THEN 100 - (SELECT COUNT(*) FROM decision_direccion) ELSE 0 END;

