INSERT INTO resolucion_gerencial (id_decision_gerencia, numero_resolucion, titulo, contenido, fecha_emision, estado)
SELECT d.id_decision_gerencia, CAST(v.numero AS VARCHAR(40)), CAST(v.titulo AS VARCHAR(150)), CAST(v.contenido AS TEXT), CAST(v.fecha AS DATE), CAST(v.estado AS VARCHAR(20))
FROM v
JOIN decision_gerencia d ON d.descripcion = v.decision
WHERE NOT EXISTS (SELECT 1 FROM resolucion_gerencial x WHERE x.numero_resolucion = v.numero)
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM resolucion_gerencial) < 100 THEN 100 - (SELECT COUNT(*) FROM resolucion_gerencial) ELSE 0 END;

