INSERT INTO reporte_direccion (tipo_reporte, modulo, descripcion, fecha_generacion)
SELECT CAST(v.tipo AS VARCHAR(60)), CAST(v.modulo AS VARCHAR(60)), CAST(v.descripcion AS TEXT), CAST(v.fecha AS TIMESTAMP)
FROM v
ORDER BY v.n
LIMIT CASE WHEN (SELECT COUNT(*) FROM reporte_direccion) < 100 THEN 100 - (SELECT COUNT(*) FROM reporte_direccion) ELSE 0 END;

